(function() {
    'use strict';

    class PLDiagnosticAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = 'Diagnostico P&L: De Garage a Serie A';
            this.version = '1.3.0';

            this.CASH_VALUES = [45000, 19860, 12204, 39783, 22410, 198454, 117362, 90176];

            this.ROUNDS = [
                {
                    title: 'Ronda 1 — El Garage (Mes 0-3): ¿Cuanto nos cuesta existir?',
                    context: 'Andrea y Diego acaban de renunciar a sus trabajos. Tienen USD 45,000 ahorrados y un MVP funcional probado con 3 empresas amigas (sin cobrar). No tienen ingresos. Estan quemando caja.',
                    pnlHtml: '<table class="table pl-diag-pnl"><thead><tr><th>Linea</th><th>USD/mes</th><th>USD trim.</th><th>% gasto</th></tr></thead><tbody><tr class="pl-diag-pnl-revenue"><td><strong>Ingresos</strong></td><td>0</td><td>0</td><td>—</td></tr><tr><td>Hosting cloud (AWS)</td><td>420</td><td>1,260</td><td>5%</td></tr><tr><td>Herramientas desarrollo</td><td>180</td><td>540</td><td>2%</td></tr><tr><td>Salarios fundadores (Andrea + Diego)</td><td>4,000</td><td>12,000</td><td>48%</td></tr><tr><td>Contadora externa</td><td>350</td><td>1,050</td><td>4%</td></tr><tr><td>Oficina coworking</td><td>280</td><td>840</td><td>3%</td></tr><tr><td>Marketing digital (Google Ads + LinkedIn)</td><td>1,500</td><td>4,500</td><td>18%</td></tr><tr><td>Viajes a clientes potenciales</td><td>800</td><td>2,400</td><td>10%</td></tr><tr><td>Legal (constitucion + contratos)</td><td>850</td><td>2,550</td><td>10%</td></tr><tr class="pl-diag-pnl-total"><td><strong>Total gastos</strong></td><td><strong>8,380</strong></td><td><strong>25,140</strong></td><td><strong>100%</strong></td></tr><tr class="pl-diag-pnl-negative"><td><strong>Resultado neto</strong></td><td><strong>-8,380</strong></td><td><strong>-25,140</strong></td><td></td></tr><tr><td><strong>Caja restante</strong></td><td></td><td><strong>19,860</strong></td><td></td></tr></tbody></table>',
                    metricsHtml: '',
                    problems: [
                        { id: 'r1p1', text: 'Salarios de fundadores demasiado altos para etapa pre-revenue (48% del gasto total, USD 2,000/mes c/u)', correct: true, points: 15, explanation: 'El benchmark pre-seed en LATAM es USD 800-1,200/mes. Reducir a USD 1,200 c/u ahorra USD 1,600/mes y extiende el runway de 2.4 a 3.5 meses.' },
                        { id: 'r1p2', text: 'Gasto en marketing digital (USD 1,500/mes) sin producto listo para vender a escala ni ingresos', correct: true, points: 15, explanation: 'Estan generando leads que no pueden convertir porque el producto es MVP. El 18% del presupuesto se quema en adquisicion prematura.' },
                        { id: 'r1p3', text: 'Runway critico: a USD 8,380/mes de burn, solo quedan 2.4 meses de caja sin plan de fundraising', correct: true, points: 15, explanation: 'Runway = Caja / Burn = 19,860 / 8,380 = 2.4 meses. En LATAM cerrar una ronda pre-seed toma 3-6 meses. Ya estan en zona de emergencia.' },
                        { id: 'r1p4', text: 'Los gastos legales de USD 2,550 son excesivos y deberian eliminarse', correct: false, points: 0, explanation: 'Los gastos legales de constitucion son one-time y razonables. No son recurrentes. Saber distinguir gastos fundacionales de operativos es clave.' },
                        { id: 'r1p5', text: 'El hosting cloud de USD 420/mes es demasiado caro para un MVP', correct: false, points: 0, explanation: 'USD 420/mes en AWS para un MVP SaaS es razonable. El problema no esta en el hosting sino en la estructura general del burn.' },
                        { id: 'r1p6', text: 'Necesitan contratar un equipo de ventas dedicado de inmediato', correct: false, points: 0, explanation: 'En etapa pre-revenue con MVP, las ventas deben ser founder-led. Contratar vendedores ahora aumentaria el burn sin justificacion.' }
                    ],
                    lesson: 'El P&L pre-revenue es un reloj de cuenta regresiva. La unica metrica que importa es el runway, y la unica variable que los fundadores controlan es el burn rate.'
                },
                {
                    title: 'Ronda 2 — Primeros Clientes (Mes 4-6): Ya vendemos... pero ¿a que costo?',
                    context: 'Nomina Clara cerro sus primeros 8 clientes (PYMEs colombianas, 15-60 empleados c/u). Total: 285 empleados gestionados. Precio: USD 3.50/empleado/mes. Andrea hace ventas. Diego hace soporte ademas de programar. Contrataron un desarrollador junior (USD 1,400/mes).',
                    pnlHtml: '<table class="table pl-diag-pnl"><thead><tr><th>Linea</th><th>USD/mes</th><th>USD trim.</th><th>vs. anterior</th></tr></thead><tbody><tr class="pl-diag-pnl-revenue"><td><strong>Ingresos (MRR)</strong></td><td>998</td><td>2,993</td><td>Nuevo</td></tr><tr><td>Hosting cloud (AWS)</td><td>680</td><td>2,040</td><td>+62%</td></tr><tr><td>Herramientas desarrollo</td><td>280</td><td>840</td><td>+56%</td></tr><tr><td>Salarios fundadores</td><td>2,400</td><td>7,200</td><td>-40%</td></tr><tr><td>Desarrollador junior</td><td>1,400</td><td>4,200</td><td>Nuevo</td></tr><tr><td>Contadora externa</td><td>350</td><td>1,050</td><td>=</td></tr><tr><td>Marketing digital</td><td>1,800</td><td>5,400</td><td>+20%</td></tr><tr><td>Customer Success (Andrea, 50% tiempo)</td><td>—</td><td>—</td><td>No contabilizado</td></tr><tr><td>Viajes a clientes</td><td>600</td><td>1,800</td><td>-25%</td></tr><tr><td>Pasarela de pagos</td><td>40</td><td>119</td><td>Nuevo</td></tr><tr class="pl-diag-pnl-total"><td><strong>Total gastos</strong></td><td><strong>7,550</strong></td><td><strong>22,649</strong></td><td></td></tr><tr class="pl-diag-pnl-negative"><td><strong>Resultado neto</strong></td><td><strong>-6,552</strong></td><td><strong>-19,656</strong></td><td></td></tr><tr><td><strong>Margen neto</strong></td><td><strong>-656%</strong></td><td></td><td></td></tr><tr><td><strong>Caja restante</strong></td><td></td><td><strong>12,204</strong></td><td></td></tr></tbody></table>',
                    metricsHtml: '<table class="table pl-diag-metrics"><thead><tr><th>Metrica</th><th>Valor</th></tr></thead><tbody><tr><td>MRR</td><td>USD 998</td></tr><tr><td>Clientes activos</td><td>8</td></tr><tr><td>Empleados gestionados</td><td>285</td></tr><tr><td>ARPU</td><td>USD 125/mes</td></tr><tr><td>CAC</td><td>USD 675</td></tr><tr><td>Tiempo onboarding</td><td>12 dias</td></tr></tbody></table>',
                    problems: [
                        { id: 'r2p1', text: 'CAC de USD 675 es insostenible vs. ARPU de USD 125/mes (payback 5.4 meses). El CAC fully-loaded con tiempo de Andrea sube a USD 1,119', correct: true, points: 10, explanation: 'El CAC real incluye marketing + salario proporcional de ventas + onboarding. (USD 1,800 + USD 600) / 2.7 clientes = USD 889. El payback es demasiado largo para una startup sin caja.' },
                        { id: 'r2p2', text: 'Costos de hosting crecen mas rapido que ingresos: USD 2.39/empleado vs. precio de USD 3.50 (hosting = 68% del precio)', correct: true, points: 10, explanation: 'El gross margin por empleado es solo 32%. El benchmark SaaS B2B es 70-85%. La arquitectura no esta optimizada para escalar.' },
                        { id: 'r2p3', text: 'El costo de Andrea en Customer Success (50% de su tiempo) no aparece en el P&L — subestima el costo real', correct: true, points: 10, explanation: 'Cuando contraten a alguien para reemplazar esa funcion, el burn subira. Un CS Manager junior en Colombia cuesta USD 1,200-1,800/mes.' },
                        { id: 'r2p4', text: 'Marketing subio de USD 1,500 a USD 1,800/mes (+20%) sin metricas de funnel que justifiquen el incremento', correct: true, points: 10, explanation: 'No hay datos de leads a demos a clientes. Sin metricas de conversion, el aumento de gasto es una apuesta ciega.' },
                        { id: 'r2p5', text: 'El precio de USD 3.50/empleado es adecuado y no necesita ajuste', correct: false, points: 0, explanation: 'El precio es demasiado bajo: con hosting a USD 2.39/empleado, el gross margin es solo 32%. Necesitaria ser mucho mayor para alcanzar margenes SaaS saludables.' },
                        { id: 'r2p6', text: 'Deberian conseguir oficina propia para parecer mas profesionales ante clientes', correct: false, points: 0, explanation: 'Correctamente eliminaron el coworking. Gastar en oficina con margen neto de -656% seria irresponsable.' },
                        { id: 'r2p7', text: 'Contratar al desarrollador junior fue un error — deberian mantener solo a Diego', correct: false, points: 0, explanation: 'Con 8 clientes y un producto SaaS, necesitan capacidad de desarrollo. La contratacion es razonable; el problema esta en otros gastos.' }
                    ],
                    lesson: 'Los primeros ingresos son emocionantes pero peligrosamente enganosos. El hecho de que "ya entra dinero" crea una falsa sensacion de progreso. El P&L revela que cada cliente nuevo cuesta mas de lo que genera en los primeros 5 meses.'
                },
                {
                    title: 'Ronda 3 — Product-Market Fit (Mes 7-9): Estamos creciendo... ¿pero hacia donde?',
                    context: 'Nomina Clara fue aceptada en una aceleradora regional que invirtio USD 50,000 por 8% de equity. Cerraron el trimestre con 28 clientes y 1,120 empleados gestionados. Onboarding bajo de 12 a 5 dias. Contrataron CS (Valentina, USD 1,600/mes) y un segundo desarrollador (USD 1,800/mes). Andrea se dedica 100% a ventas.',
                    pnlHtml: '<table class="table pl-diag-pnl"><thead><tr><th>Linea</th><th>USD/mes</th><th>USD trim.</th><th>vs. anterior</th></tr></thead><tbody><tr class="pl-diag-pnl-revenue"><td><strong>Ingresos (MRR)</strong></td><td>3,920</td><td>11,760</td><td>+293%</td></tr><tr><td colspan="4" style="background:#f0f3f8;font-weight:600;">Costo de Ventas (COGS):</td></tr><tr><td>Hosting cloud (AWS)</td><td>1,350</td><td>4,050</td><td>+99%</td></tr><tr><td>Pasarela de pagos</td><td>157</td><td>471</td><td>+296%</td></tr><tr><td>Customer Success (Valentina)</td><td>1,600</td><td>4,800</td><td>Nuevo</td></tr><tr class="pl-diag-pnl-total"><td><strong>Total COGS</strong></td><td><strong>3,107</strong></td><td><strong>9,321</strong></td><td></td></tr><tr><td><strong>Margen bruto</strong></td><td><strong>813</strong></td><td><strong>2,439</strong></td><td><strong>20.7%</strong></td></tr><tr><td colspan="4" style="background:#f0f3f8;font-weight:600;">Gastos Operativos:</td></tr><tr><td>Salarios fundadores</td><td>3,000</td><td>9,000</td><td>+25%</td></tr><tr><td>Desarrollador junior #1</td><td>1,400</td><td>4,200</td><td>=</td></tr><tr><td>Desarrollador #2</td><td>1,800</td><td>5,400</td><td>Nuevo</td></tr><tr><td>Herramientas desarrollo</td><td>420</td><td>1,260</td><td>+50%</td></tr><tr><td>Contadora externa</td><td>350</td><td>1,050</td><td>=</td></tr><tr><td>Oficina propia (upgrade)</td><td>950</td><td>2,850</td><td>Nuevo</td></tr><tr><td>Marketing digital</td><td>3,200</td><td>9,600</td><td>+78%</td></tr><tr><td>Viajes/eventos</td><td>1,100</td><td>3,300</td><td>+83%</td></tr><tr class="pl-diag-pnl-total"><td><strong>Total OpEx</strong></td><td><strong>12,220</strong></td><td><strong>36,660</strong></td><td></td></tr><tr class="pl-diag-pnl-negative"><td><strong>Resultado operativo</strong></td><td><strong>-11,407</strong></td><td><strong>-34,221</strong></td><td></td></tr><tr><td><strong>Margen operativo</strong></td><td><strong>-291%</strong></td><td></td><td></td></tr><tr><td><strong>Caja restante</strong></td><td></td><td><strong>39,783</strong></td><td></td></tr></tbody></table>',
                    metricsHtml: '<table class="table pl-diag-metrics"><thead><tr><th>Metrica</th><th>Valor</th><th>vs. anterior</th></tr></thead><tbody><tr><td>MRR</td><td>USD 3,920</td><td>+293%</td></tr><tr><td>Clientes activos</td><td>28</td><td>+250%</td></tr><tr><td>ARPU</td><td>USD 140/mes</td><td>+12%</td></tr><tr><td>Churn mensual</td><td>3.5%</td><td>Primera medicion</td></tr><tr><td>CAC</td><td>USD 457</td><td>-32%</td></tr><tr><td>LTV (estimado)</td><td>USD 4,000</td><td></td></tr><tr><td>LTV/CAC</td><td>8.8x</td><td></td></tr></tbody></table>',
                    problems: [
                        { id: 'r3p1', text: 'Margen bruto de 20.7% es inaceptable para SaaS B2B (benchmark: 70-85%). Cada dolar genera solo 21 centavos para cubrir OpEx', correct: true, points: 10, explanation: 'Un gross margin de 20% significa que la startup no es un negocio SaaS — es un negocio de servicios disfrazado de software. CS escala linealmente con clientes, no con ingresos.' },
                        { id: 'r3p2', text: 'Gasto en oficina propia (USD 950/mes) es innecesario y se come todo el margen bruto (USD 813/mes)', correct: true, points: 10, explanation: 'Con 5 personas podrian trabajar remoto. USD 190/persona/mes cuando el margen bruto total es USD 813/mes. La oficina es un gasto de senalizacion, no productivo.' },
                        { id: 'r3p3', text: 'Churn mensual de 3.5% es una bomba de tiempo (34.5% anual). De cada 3 clientes adquiridos, pierden 1 al anio', correct: true, points: 10, explanation: 'Con 28 clientes y 3.5% churn/mes, en 12 meses sin adquirir nuevos quedan solo 18.3. Necesitan adquirir 3.5 clientes/mes solo para crecer.' },
                        { id: 'r3p4', text: 'Fundadores se subieron el sueldo de USD 1,200 a USD 1,500 c/u (+25%) con margen bruto de solo USD 813/mes', correct: true, points: 10, explanation: 'Los salarios de fundadores (USD 3,000/mes) son 3.7x el margen bruto. El aumento no esta justificado por la economia del negocio.' },
                        { id: 'r3p5', text: 'El CAC de USD 457 es demasiado alto y debe reducirse urgentemente', correct: false, points: 0, explanation: 'El CAC mejoro 32% (de USD 675 a USD 457) y el LTV/CAC de 8.8x es excelente. El CAC no es el problema principal en esta ronda.' },
                        { id: 'r3p6', text: 'La inversion de la aceleradora (8% equity por USD 50K) diluyo demasiado a los fundadores', correct: false, points: 0, explanation: 'Es una valoracion implicita de USD 625K — razonable para etapa seed en LATAM. Sin ese capital, la empresa habria muerto.' },
                        { id: 'r3p7', text: 'Deberian reducir el equipo de desarrollo para ahorrar costos', correct: false, points: 0, explanation: 'Con 28 clientes y crecimiento de 293%, necesitan capacidad de desarrollo. El problema no es el equipo tecnico sino la estructura de costos y pricing.' }
                    ],
                    lesson: 'El crecimiento de ingresos no es lo mismo que la salud del negocio. El MRR crecio 293% pero el margen bruto es 20.7% — cada dolar de ingreso genera solo 21 centavos para cubrir gastos operativos.'
                },
                {
                    title: 'Ronda 4 — Crecimiento Agresivo (Mes 10-12): Mas clientes, mas problemas',
                    context: 'Nomina Clara lanzo en Mexico (segundo mercado). Equipo de 9 personas. Andrea contrato un vendedor (Santiago, USD 2,000/mes + comision) y un segundo CS. Diego contrato un tercer dev para regulacion mexicana. 52 clientes, 2,340 empleados gestionados. Pero algo no cuadra.',
                    pnlHtml: '<table class="table pl-diag-pnl"><thead><tr><th>Linea</th><th>USD/mes</th><th>USD trim.</th><th>vs. anterior</th></tr></thead><tbody><tr class="pl-diag-pnl-revenue"><td><strong>Ingresos (MRR)</strong></td><td>8,190</td><td>24,570</td><td>+109%</td></tr><tr><td colspan="4" style="background:#f0f3f8;font-weight:600;">COGS:</td></tr><tr><td>Hosting cloud</td><td>2,100</td><td>6,300</td><td>+56%</td></tr><tr><td>Pasarela de pagos</td><td>328</td><td>983</td><td>+109%</td></tr><tr><td>Customer Success (2 personas)</td><td>3,200</td><td>9,600</td><td>+100%</td></tr><tr><td>Soporte tecnico L1 (freelancer)</td><td>800</td><td>2,400</td><td>Nuevo</td></tr><tr class="pl-diag-pnl-total"><td><strong>Total COGS</strong></td><td><strong>6,428</strong></td><td><strong>19,283</strong></td><td></td></tr><tr><td><strong>Margen bruto</strong></td><td><strong>1,762</strong></td><td><strong>5,287</strong></td><td><strong>21.5%</strong></td></tr><tr><td colspan="4" style="background:#f0f3f8;font-weight:600;">Gastos Operativos:</td></tr><tr><td>Salarios fundadores</td><td>3,500</td><td>10,500</td><td>+17%</td></tr><tr><td>Equipo desarrollo (3 devs)</td><td>5,200</td><td>15,600</td><td>+44%</td></tr><tr><td>Vendedor Santiago — base</td><td>2,000</td><td>6,000</td><td>Nuevo</td></tr><tr><td>Comisiones ventas</td><td>780</td><td>2,340</td><td>Nuevo</td></tr><tr><td>Herramientas (dev+CRM+analytics)</td><td>890</td><td>2,670</td><td>+112%</td></tr><tr><td>Oficina</td><td>950</td><td>2,850</td><td>=</td></tr><tr><td>Marketing digital</td><td>4,800</td><td>14,400</td><td>+50%</td></tr><tr><td>Marketing eventos Mexico</td><td>2,200</td><td>6,600</td><td>Nuevo</td></tr><tr><td>Viajes (COL + MEX)</td><td>2,400</td><td>7,200</td><td>+118%</td></tr><tr><td>Contadora + gestoria Mexico</td><td>900</td><td>2,700</td><td>+157%</td></tr><tr><td>Legal Mexico</td><td>600</td><td>1,800</td><td>Nuevo</td></tr><tr class="pl-diag-pnl-total"><td><strong>Total OpEx</strong></td><td><strong>24,220</strong></td><td><strong>72,660</strong></td><td></td></tr><tr class="pl-diag-pnl-negative"><td><strong>Resultado operativo</strong></td><td><strong>-22,458</strong></td><td><strong>-67,373</strong></td><td></td></tr><tr><td><strong>Margen operativo</strong></td><td><strong>-274%</strong></td><td></td><td></td></tr><tr><td><strong>Caja restante</strong></td><td></td><td><strong>22,410</strong></td><td>⚠️</td></tr></tbody></table>',
                    metricsHtml: '<table class="table pl-diag-metrics"><thead><tr><th>Metrica</th><th>Valor</th><th>Nota</th></tr></thead><tbody><tr><td>MRR</td><td>USD 8,190</td><td>+109%</td></tr><tr><td>Clientes Colombia</td><td>35</td><td>ARPU USD 148</td></tr><tr><td>Clientes Mexico</td><td>17</td><td>ARPU USD 168</td></tr><tr><td>Churn Colombia</td><td>2.8%</td><td>Mejoro</td></tr><tr><td>Churn Mexico</td><td>6.2%</td><td>⚠️ Alto</td></tr><tr><td>CAC Colombia</td><td>USD 380</td><td>-17%</td></tr><tr><td>CAC Mexico</td><td>USD 1,240</td><td>⚠️</td></tr><tr><td>Runway</td><td>0.7 meses</td><td>⚠️⚠️⚠️</td></tr></tbody></table>',
                    problems: [
                        { id: 'r4p1', text: 'Mexico destruye la economia unitaria: CAC $1,240 (3.3x Colombia), churn 6.2% (2.2x Colombia), LTV/CAC solo 2.2x', correct: true, points: 10, explanation: 'LTV Mexico = USD 168 / 0.062 = USD 2,710. LTV/CAC = 2.2x, debajo del minimo de 3x. Mexico esta subsidiado por Colombia.' },
                        { id: 'r4p2', text: 'Margen bruto estancado en 21.5% pese a duplicar ingresos — no hay economias de escala', correct: true, points: 8, explanation: 'El COGS crece proporcionalmente al ingreso. CS escala linealmente y hosting no muestra eficiencia. Esto no es un modelo SaaS escalable.' },
                        { id: 'r4p3', text: 'Comisiones de ventas sin estructura de retencion — Santiago no tiene incentivo para evitar churn', correct: true, points: 8, explanation: 'Si la comision es por firma sin penalizacion por churn, hay incentivo para cerrar clientes malos. El estandar SaaS es comision sobre ACV con clawback.' },
                        { id: 'r4p4', text: 'Runway en zona roja: 0.7 meses (USD 22,410 / USD 30,648 gastos totales). La empresa muere en 3 semanas', correct: true, points: 10, explanation: 'Estan en situacion "default dead" de Paul Graham. Negociar con inversionistas con menos de 1 mes de caja destruye la valuacion.' },
                        { id: 'r4p5', text: 'Fundadores se subieron el sueldo a USD 1,750 c/u con runway de 0.7 meses — senal roja para inversionistas', correct: true, points: 8, explanation: 'Cada aumento de sueldo con caja critica demuestra falta de disciplina financiera. Un VC en due diligence notaria este patron.' },
                        { id: 'r4p6', text: 'El ARPU de Mexico (USD 168) es demasiado bajo comparado con Colombia', correct: false, points: 0, explanation: 'El ARPU de Mexico (USD 168) es en realidad mayor que el de Colombia (USD 148). El problema no es el precio sino el CAC y churn.' },
                        { id: 'r4p7', text: 'Han contratado demasiados desarrolladores — deberian mantener solo a Diego', correct: false, points: 0, explanation: 'Con 52 clientes en 2 paises y regulacion diferente, necesitan equipo tecnico. El problema es la expansion prematura a Mexico, no el equipo.' },
                        { id: 'r4p8', text: 'Los viajes a clientes son innecesarios y deberian eliminarse completamente', correct: false, points: 0, explanation: 'En ventas B2B en LATAM, las visitas presenciales son parte del proceso. El volumen de viajes es alto por operar en 2 paises, no por ineficiencia.' }
                    ],
                    lesson: 'Crecer en dos mercados simultaneamente con caja limitada es la decision que mata mas startups en LATAM. El P&L segmentado muestra que Colombia sola era viable; Mexico destruye valor.'
                },
                {
                    title: 'Ronda 5 — Crisis de Margenes (Mes 13-15): El equipo crece, los margenes se comprimen',
                    context: 'Nomina Clara cerro una ronda pre-seed de USD 250,000 (Fondo Acelera LATAM, 15% equity). Se pauso Mexico. Equipo de 14 personas. El fondo quiere ver USD 25K MRR para mes 18. Ingresos crecen pero los gastos crecen mas rapido.',
                    pnlHtml: '<table class="table pl-diag-pnl"><thead><tr><th>Linea</th><th>USD/mes</th><th>USD trim.</th><th>vs. anterior</th></tr></thead><tbody><tr class="pl-diag-pnl-revenue"><td><strong>Ingresos SaaS (MRR)</strong></td><td>14,350</td><td>43,050</td><td>+75%</td></tr><tr class="pl-diag-pnl-revenue"><td>Servicios de implementacion</td><td>1,200</td><td>3,600</td><td>Nuevo</td></tr><tr class="pl-diag-pnl-revenue"><td><strong>Ingresos totales</strong></td><td><strong>15,550</strong></td><td><strong>46,650</strong></td><td></td></tr><tr><td colspan="4" style="background:#f0f3f8;font-weight:600;">COGS:</td></tr><tr><td>Hosting (migracion parcial)</td><td>2,450</td><td>7,350</td><td>+17%</td></tr><tr><td>Pasarela de pagos</td><td>622</td><td>1,866</td><td>+90%</td></tr><tr><td>Customer Success (3 personas)</td><td>4,800</td><td>14,400</td><td>+50%</td></tr><tr><td>Soporte tecnico (2 freelancers)</td><td>1,600</td><td>4,800</td><td>+100%</td></tr><tr class="pl-diag-pnl-total"><td><strong>Total COGS</strong></td><td><strong>9,472</strong></td><td><strong>28,416</strong></td><td></td></tr><tr><td><strong>Margen bruto</strong></td><td><strong>6,078</strong></td><td><strong>18,234</strong></td><td><strong>39.1%</strong></td></tr><tr><td colspan="4" style="background:#f0f3f8;font-weight:600;">Gastos Operativos:</td></tr><tr><td>Salarios fundadores</td><td>4,500</td><td>13,500</td><td>+29%</td></tr><tr><td>Equipo desarrollo (4 devs + 1 QA)</td><td>9,200</td><td>27,600</td><td>+77%</td></tr><tr><td>Equipo ventas (Santiago + 1 SDR)</td><td>3,800</td><td>11,400</td><td>+53%</td></tr><tr><td>Comisiones ventas</td><td>1,450</td><td>4,350</td><td>+86%</td></tr><tr><td>People Ops / HR</td><td>1,500</td><td>4,500</td><td>Nuevo</td></tr><tr><td>Herramientas (Slack, Notion, HubSpot...)</td><td>1,680</td><td>5,040</td><td>+89%</td></tr><tr><td>Oficina (ampliacion)</td><td>1,800</td><td>5,400</td><td>+89%</td></tr><tr><td>Marketing digital</td><td>4,200</td><td>12,600</t