tr><td>Beneficios equipo</td><td>1,200</td><td>3,600</td><td>+33%</td></tr><tr class="pl-diag-pnl-total"><td><strong>Total OpEx</strong></td><td><strong>38,950</strong></td><td><strong>116,850</strong></td><td></td></tr><tr class="pl-diag-pnl-negative"><td><strong>Resultado operativo</strong></td><td><strong>-9,062</strong></td><td><strong>-27,186</strong></td><td></td></tr><tr><td><strong>Margen operativo</strong></td><td><strong>-22%</strong></td><td></td><td>Mejoro desde -42%</td></tr><tr><td><strong>Caja restante</strong></td><td></td><td><strong>90,176</strong></td><td></td></tr><tr><td><strong>Runway</strong></td><td></td><td><strong>10 meses</strong></td><td></td></tr></tbody></table>',
