            this._pendingAdvance = null;
        }

        initialize(state) {
            // Reset domainState on a fresh start OR when there is no completed-round history
            // (the framework calls initialize() after Undo pops the last row to empty). The old
            // guard only checked for an empty domainState, so undo-to-start left the already
            // counted totals in place and the next submit double-counted them. (v1.3.0 fix)
            if (!state.domainState || Object.keys(state.domainState).length === 0 || !state.history || state.history.length === 0) {
                state.domainState = {
                    totalScore: 0,
                    maxPossibleScore: 0,
                    roundScores: [],
                    roundMaxScores: [],
                    correctCounts: [],
                    totalCorrects: [],
                    percentages: []
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = { selectedProblems: '' };
            }
            this._bindModalClose();
            this._updateBriefing(state);
        }

        validateDecisions(decisions) {
            var selected = [];
            var allCbs = document.getElementsByClassName('pl421-problem-checkbox');
            for (var j = 0; j < allCbs.length; j++) {
                if (allCbs[j].checked) selected.push(allCbs[j].value);
            }
            if (selected.length === 0) {
                window.mySimulation.uiManager.showNotification(
                    window.mySimulation.t('no_selection_warning'), 'warning'
                );
                return false;
            }
            decisions.selectedProblems = selected.join(',');
            return true;
        }

        calculateResults(state) {
            var period = state.currentPeriod || 1;
            var idx = Math.min(period - 1, this.ROUNDS.length - 1);
            var round = this.ROUNDS[idx];
            var selected = state.decisions.selectedProblems.split(',');

            var score = 0, maxScore = 0, correctFound = 0, totalCorrect = 0, penalty = 0;

            round.problems.forEach(function(p) {
                if (p.correct) {
                    maxScore += p.points;
                    totalCorrect++;
                    if (selected.indexOf(p.id) !== -1) {
                        score += p.points;
                        correctFound++;
                    }
                } else if (selected.indexOf(p.id) !== -1) {
                    penalty += 5;
                }
            });

            var finalScore = Math.max(0, score - penalty);
            var pct = maxScore > 0 ? Math.round((finalScore / maxScore) * 100) : 0;

            state.domainState.totalScore += finalScore;
            state.domainState.maxPossibleScore += maxScore;
            state.domainState.roundScores.push(finalScore);
            state.domainState.roundMaxScores.push(maxScore);
            state.domainState.correctCounts.push(correctFound);
            state.domainState.totalCorrects.push(totalCorrect);
            state.domainState.percentages.push(pct);

            this._showFeedbackModal(round, selected, finalScore, maxScore, correctFound, totalCorrect, penalty, state.currentPeriod);

            var self = this;
            // Advance to the NEXT round when the feedback modal closes. Use the captured
            // `period` (the round just graded): the framework increments state.currentPeriod
            // synchronously after calculateResults returns, so by modal-close time reading
            // state.currentPeriod + 1 pointed TWO rounds ahead — Round 2 was never shown and
            // every later round was graded against the wrong P&L. Guard the final round so the
            // modal-close does not try to render past the end. (v1.3.0 fix)
            var maxP = (window.mySimulation && window.mySimulation.state && window.mySimulation.state.maxPeriods) || this.ROUNDS.length;
            this._pendingAdvance = (period < maxP) ? function() {
                self._updateBriefing({ currentPeriod: period + 1, domainState: state.domainState });
            } : null;

            return {
                period: period,
                roundName: round.title,
                score: finalScore,
                maxScore: maxScore,
                correctFound: correctFound,
                totalCorrect: totalCorrect,
                penalty: penalty,
                percentage: pct,
                totalScore: state.domainState.totalScore,
                totalMaxScore: state.domainState.maxPossibleScore
            };
        }

        _bindModalClose() {
            var self = this;
            var overlay = document.getElementById('roundFeedbackOverlay');
            var btn = document.getElementById('modalContinueBtn');
            var modal = document.getElementById('roundFeedbackModal');
            if (btn && !btn._pl421Bound) {
                btn.addEventListener('click', function() { self._closeModal(); });
                btn._pl421Bound = true;
            }
            if (overlay && !overlay._pl421Bound) {
                overlay.addEventListener('click', function() { self._closeModal(); });
                overlay._pl421Bound = true;
            }
            if (modal && !modal._pl421KeyBound) {
                document.addEventListener('keydown', function(e) {
                    if (e.key === 'Escape' && modal.classList.contains('pl421-modal-open')) {
                        self._closeModal();
                    }
                });
                modal._pl421KeyBound = true;
            }
        }

        _closeModal() {
            var modal = document.getElementById('roundFeedbackModal');
            if (modal) {
                modal.classList.remove('pl421-modal-open');
                modal.setAttribute('aria-hidden', 'true');
            }
            document.body.style.overflow = '';
            if (typeof this._pendingAdvance === 'function') {
                var fn = this._pendingAdvance;
                this._pendingAdvance = null;
                fn();
            }
        }

        _showFeedbackModal(round, selected, score, maxScore, correctFound, totalCorrect, penalty, periodNum) {
            this._bindModalClose();
            var modal = document.getElementById('roundFeedbackModal');
            var titleEl = document.getElementById('modalRoundTitle');
            var scoreEl = document.getElementById('modalRoundScore');
            var bodyEl = document.getElementById('modalRoundBody');
            var btnEl = document.getElementById('modalContinueBtn');
            if (!modal || !titleEl || !scoreEl || !bodyEl) return;

            titleEl.innerHTML = round.title;

            var scoreHtml = '<span class="pl421-score-big">' + score + ' / ' + maxScore + '</span> ' + window.mySimulation.t('points_label');
            if (penalty > 0) {
                scoreHtml += ' · <span style="color:#fbbf24;">' + window.mySimulation.t('penalty_label') + ': -' + penalty + '</span>';
            }
            scoreHtml += '<br><span style="color:#9aa6cf; font-size:0.9rem; font-weight:500;">' + correctFound + ' ' + window.mySimulation.t('of_label') + ' ' + totalCorrect + ' ' + window.mySimulation.t('correct_identified') + '</span>';
            scoreEl.innerHTML = scoreHtml;

            var html = '';
            round.problems.forEach(function(p) {
                var was = selected.indexOf(p.id) !== -1;
                if (p.correct && was) {
                    html += '<div class="pl-diag-fb-correct">✓ <strong>' + p.text + '</strong><br>' + p.explanation + '</div>';
                } else if (p.correct && !was) {
                    html += '<div class="pl-diag-fb-missed">✗ <strong>' + window.mySimulation.t('missed_label') + ':</strong> ' + p.text + '<br>' + p.explanation + '</div>';
                } else if (!p.correct && was) {
                    html += '<div class="pl-diag-fb-wrong">! <strong>' + window.mySimulation.t('wrong_label') + ':</strong> ' + p.text + '<br>' + p.explanation + '</div>';
                }
            });
            html += '<div class="pl-diag-fb-lesson"><strong>' + window.mySimulation.t('lesson_label') + ':</strong> ' + round.lesson + '</div>';
            bodyEl.innerHTML = html;

            var totalRounds = this.ROUNDS.length;
            if (btnEl) {
                btnEl.textContent = (periodNum >= totalRounds)
                    ? window.mySimulation.t('finish_btn')
                    : window.mySimulation.t('continue_btn');
            }

            modal.classList.add('pl421-modal-open');
            modal.setAttribute('aria-hidden', 'false');
            document.body.style.overflow = 'hidden';
            var dialog = modal.querySelector('.pl421-modal-dialog');
            if (dialog) dialog.scrollTop = 0;
        }

        _updateBriefing(state) {
            var idx = Math.min((state.currentPeriod || 1) - 1, this.ROUNDS.length - 1);
            var round = this.ROUNDS[idx];

            var titleEl = document.getElementById('roundTitle');
            if (titleEl) titleEl.innerHTML = round.title;

            var ctxEl = document.getElementById('roundContext');
            if (ctxEl) ctxEl.innerHTML = round.context;

            var pnlEl = document.getElementById('pnlContainer');
            if (pnlEl) pnlEl.innerHTML = round.pnlHtml;

            var metEl = document.getElementById('metricsContainer');
            if (metEl) metEl.innerHTML = round.metricsHtml || '';

            var probEl = document.getElementById('problemsContainer');
            if (probEl) {
                var html = '';
                round.problems.forEach(function(p) {
                    html += '<label class="pl421-sim-problem-item">';
                    html += '<input type="checkbox" class="pl421-problem-checkbox" value="' + p.id + '">';
                    html += '<span>' + p.text + '</span>';
                    html += '</label>';
                });
                probEl.innerHTML = html;
                var cbs = probEl.querySelectorAll('.pl421-problem-checkbox');
                cbs.forEach(function(cb) {
                    cb.addEventListener('change', function() {
                        var item = cb.closest('.pl421-sim-problem-item');
                        if (item) item.classList.toggle('selected', cb.checked);
                    });
                });
            }

            var cashEl = document.getElementById('cashDisplay');
            if (cashEl) {
                var cashIdx = Math.min((state.currentPeriod || 1), this.CASH_VALUES.length - 1);
                cashEl.textContent = '$' + this.CASH_VALUES[cashIdx].toLocaleString();
            }

            var accEl = document.getElementById('accuracyDisplay');
            if (accEl && state.domainState && state.domainState.maxPossibleScore > 0) {
                var totalPct = Math.round((state.domainState.totalScore / state.domainState.maxPossibleScore) * 100);
                accEl.textContent = totalPct + '%';
            } else if (accEl) {
                accEl.textContent = '0%';
            }

            var corrEl = document.getElementById('correctDisplay');
            if (corrEl && state.domainState && state.domainState.correctCounts) {
                var sumCorr = state.domainState.correctCounts.reduce(function(a, b) { return a + b; }, 0);
                var sumTotal = state.domainState.totalCorrects.reduce(function(a, b) { return a + b; }, 0);
                corrEl.textContent = sumCorr + ' / ' + sumTotal;
            }

            window.scrollTo({ top: 0, behavior: 'smooth' });
        }

