        getPerformanceSummary(history) {
            if (!history.length) return {};
            var totalScore = 0, totalMax = 0, totalCorrect = 0, totalProblems = 0;
            history.forEach(function(h) {
                totalScore += (h.results ? h.results.score : 0) || 0;
                totalMax += (h.results ? h.results.maxScore : 0) || 0;
                totalCorrect += (h.results ? h.results.correctFound : 0) || 0;
                totalProblems += (h.results ? h.results.totalCorrect : 0) || 0;
            });
            var pct = totalMax > 0 ? Math.round((totalScore / totalMax) * 100) : 0;

            var performance = 'Aprendiz';
            var insights = [];
            if (pct >= 85) {
                performance = 'CFO Experto';
                insights.push('Diagnostico excepcional. Identificaste la mayoria de problemas criticos en cada etapa.');
                insights.push('Tu lectura diagnostica de estados financieros de startups es de nivel profesional.');
            } else if (pct >= 70) {
                performance = 'Analista Senior';
                insights.push('Buen ojo para los problemas principales. Algunas senales sutiles se escaparon.');
                insights.push('Revisa especialmente NRR, burn multiple, y patrones entre rondas.');
            } else if (pct >= 50) {
                performance = 'Analista Junior';
                insights.push('Identificaste los problemas mas obvios pero algunos criticos pasaron desapercibidos.');
                insights.push('Recuerda: el P&L de una startup cuenta una historia diferente en cada etapa.');
            } else {
                performance = 'Aprendiz';
                insights.push('El diagnostico de P&L requiere practica. Cada linea refleja una decision operativa.');
                insights.push('Enfocate en runway, margen bruto, y unit economics como indicadores clave.');
            }

            return {
                totalScore: totalScore,
                totalMax: totalMax,
                percentage: pct,
                correctIdentifications: totalCorrect + ' de ' + totalProblems,
                performance: performance,
                insights: insights
            };
        }

        getHint(state, results) {
            if (!results) return null;
            if (results.percentage >= 85) return window.mySimulation.t('hint_excellent');
            if (results.percentage >= 60) return window.mySimulation.t('hint_good');
            if (results.percentage >= 30) return window.mySimulation.t('hint_fair');
            return window.mySimulation.t('hint_needs_work');
        }

